DESCRIBE crypto_ai.fix129_stage_timing;
SELECT correlation_id, symbol, interval_code, UNIX_TIMESTAMP(observed_at) AS obs_epoch, stage, UNIX_TIMESTAMP(started_at) AS start_epoch, UNIX_TIMESTAMP(finished_at) AS finish_epoch, elapsed_ms, outcome, thread_name FROM crypto_ai.fix129_stage_timing WHERE started_at BETWEEN FROM_UNIXTIME(1791741295) AND FROM_UNIXTIME(1791741310) OR started_at BETWEEN FROM_UNIXTIME(1791741595) AND FROM_UNIXTIME(1791741620) OR started_at BETWEEN FROM_UNIXTIME(1791747595) AND FROM_UNIXTIME(1791747840) OR started_at BETWEEN FROM_UNIXTIME(1791761695) AND FROM_UNIXTIME(1791761710) OR started_at BETWEEN FROM_UNIXTIME(1791764995) AND FROM_UNIXTIME(1791765012) OR started_at BETWEEN FROM_UNIXTIME(1791766915) AND FROM_UNIXTIME(1791766930) OR started_at BETWEEN FROM_UNIXTIME(1791768355) AND FROM_UNIXTIME(1791768370) OR started_at BETWEEN FROM_UNIXTIME(1791776155) AND FROM_UNIXTIME(1791776170) OR started_at BETWEEN FROM_UNIXTIME(1791778500) AND FROM_UNIXTIME(1791778550) OR started_at BETWEEN FROM_UNIXTIME(1791788215) AND FROM_UNIXTIME(1791788230) OR started_at BETWEEN FROM_UNIXTIME(1791788695) AND FROM_UNIXTIME(1791788725) ORDER BY started_at LIMIT 200;